import { useEffect } from 'react';
import { useSelector } from 'react-redux';

import { hasErrorType } from '../helpers/errors';
import { conversationByID } from '../logic/conversations/conversationsSelectors';
import { ConversationState } from '../logic/conversations/conversationsTypes';
import { messageByID } from '../logic/messages/messagesSelectors';
import { MessageState } from '../logic/messages/messagesTypes';
import { RootState } from '../logic/store';

const cacheEntryIsFailedLoading = (
    conversationMode: boolean,
    cacheEntry: MessageState | ConversationState | undefined
) => {
    if (conversationMode) {
        return hasErrorType(cacheEntry?.errors, 'notExist');
    }
    const messageExtended = cacheEntry as MessageState;
    return messageExtended?.data?.ID && !messageExtended?.data?.Subject;
};

interface Props {
    conversationMode: boolean;
    elementID?: string;
    onBack: () => void;
    loading: boolean;
    labelID: string;
}

export const useShouldMoveOut = ({ conversationMode, elementID = '', labelID, loading, onBack }: Props) => {
    const message = useSelector((state: RootState) => messageByID(state, { ID: elementID }));
    const conversation = useSelector((state: RootState) => conversationByID(state, { ID: elementID }));
    const cacheEntry = conversationMode ? conversation : message;

    const onChange = (labelIds: string[] | undefined) => {
        // Move out if the element is not present in the cache anymore
        if (!labelIds) {
            onBack();
            return;
        }

        // Move out if the element doesn't contain the current label
        if (!labelIds.includes(labelID)) {
            onBack();
            return;
        }
    };

    useEffect(() => {
        if (!loading && !conversationMode && message?.data?.LabelIDs) {
            // Not sure why, but message from the selector can be a render late here
            onChange(message?.data?.LabelIDs);
        }
    }, [message?.data?.LabelIDs, loading]);

    useEffect(() => {
        if (!loading && conversationMode && conversation?.Conversation.Labels) {
            // Not sure why, but message from the selector can be a render late here
            onChange(conversation?.Conversation.Labels.map((label) => label.ID));
        }
    }, [conversation?.Conversation.Labels, loading]);

    useEffect(() => {
        if (!elementID || !cacheEntry) {
            return;
        }

        // Move out of a non existing element
        if (!loading && (!cacheEntry || cacheEntryIsFailedLoading(conversationMode, cacheEntry))) {
            onBack();
            return;
        }
    }, [elementID, loading, conversationMode, cacheEntry]);
};

import { c } from 'ttag';

import { IconName } from '@proton/components';
import { MAILBOX_LABEL_IDS, SHOW_MOVED } from '@proton/shared/lib/constants';
import { hasBit } from '@proton/shared/lib/helpers/bitset';
import { toMap } from '@proton/shared/lib/helpers/object';
import { MailSettings } from '@proton/shared/lib/interfaces';
import { Folder } from '@proton/shared/lib/interfaces/Folder';
import { Label } from '@proton/shared/lib/interfaces/Label';

import { LABELS_AUTO_READ, LABELS_UNMODIFIABLE_BY_USER, LABEL_IDS_TO_HUMAN, getLabelIDsToI18N } from '../constants';
import { MessageWithOptionalBody } from '../logic/messages/messagesTypes';
import { Conversation } from '../models/conversation';
import { Element } from '../models/element';
import { getLabelIDs } from './elements';

const { INBOX, TRASH, SPAM, ARCHIVE, SENT, DRAFTS, ALL_SENT, ALL_DRAFTS, SCHEDULED, OUTBOX, STARRED } =
    MAILBOX_LABEL_IDS;
const DEFAULT_FOLDERS = [INBOX, TRASH, SPAM, ARCHIVE, SENT, DRAFTS, SCHEDULED, OUTBOX];

export type LabelChanges = { [labelID: string]: boolean };

export interface FolderInfo {
    icon: IconName;
    name: string;
    to: string;
    color?: string;
    parentID?: string | number;
}

interface FolderMap {
    [id: string]: FolderInfo;
}

const alwaysMessageLabels = [DRAFTS, ALL_DRAFTS, SENT, ALL_SENT];

export const getHumanLabelID = (labelID: string) => LABEL_IDS_TO_HUMAN[labelID as MAILBOX_LABEL_IDS] || labelID;

export const getI18nLabelID = (labelID: string) =>
    getLabelIDsToI18N()[labelID as MAILBOX_LABEL_IDS] || getHumanLabelID(labelID);

export const getLabelName = (labelID: string, labels: Label[] = [], folders: Folder[] = []): string => {
    if (labelID in LABEL_IDS_TO_HUMAN) {
        return getI18nLabelID(labelID);
    }

    const labelsMap = toMap(labels, 'ID');
    if (labelID in labelsMap) {
        return labelsMap[labelID]?.Name || labelID;
    }

    const foldersMap = toMap(folders, 'ID');
    if (labelID in foldersMap) {
        return foldersMap[labelID]?.Name || labelID;
    }

    return labelID;
};

export const isCustomLabelOrFolder = (labelID: string) =>
    !Object.values(MAILBOX_LABEL_IDS).includes(labelID as MAILBOX_LABEL_IDS);

export const isAlwaysMessageLabels = (labelID: string) => alwaysMessageLabels.includes(labelID as MAILBOX_LABEL_IDS);

export const labelIncludes = (labelID: string, ...labels: (MAILBOX_LABEL_IDS | string)[]) =>
    labels.includes(labelID as MAILBOX_LABEL_IDS);

export const isCustomLabel = (labelID: string, labels: Label[] = []) => labels.some((label) => label.ID === labelID);

export const isLabel = (labelID: string, labels: Label[] = []) =>
    labelIncludes(labelID, STARRED) || isCustomLabel(labelID, labels);

export const isCustomFolder = (labelID: string, folders: Folder[] = []) =>
    folders.some((folder) => folder.ID === labelID);

export const getStandardFolders = (): FolderMap => ({
    [INBOX]: {
        icon: 'inbox',
        name: c('Mailbox').t`Inbox`,
        to: '/inbox',
    },
    [TRASH]: {
        icon: 'trash',
        name: c('Mailbox').t`Trash`,
        to: '/trash',
    },
    [SPAM]: {
        icon: 'fire',
        name: c('Mailbox').t`Spam`,
        to: '/spam',
    },
    [ARCHIVE]: {
        icon: 'archive-box',
        name: c('Mailbox').t`Archive`,
        to: '/archive',
    },
    [SENT]: {
        icon: 'paper-plane',
        name: c('Mailbox').t`Sent`,
        to: `/${LABEL_IDS_TO_HUMAN[SENT]}`,
    },
    [ALL_SENT]: {
        icon: 'paper-plane',
        name: c('Mailbox').t`Sent`,
        to: `/${LABEL_IDS_TO_HUMAN[ALL_SENT]}`,
    },
    [DRAFTS]: {
        icon: 'file-lines',
        name: c('Mailbox').t`Drafts`,
        to: `/${LABEL_IDS_TO_HUMAN[DRAFTS]}`,
    },
    [ALL_DRAFTS]: {
        icon: 'file-lines',
